src = open('/app/submission/planner.py').read()

start = src.index("OPTIMAL_STRATEGIES = (")
end = src.index("# --------------------------------------------------------------------------\n# Line oriented IO")

new = '''OPTIMAL_STRATEGIES = (
    ("highs", {"presolve": True}),
    ("highs-ds", {"presolve": True}),
    ("highs-ipm", {"presolve": True, "ipm_optimality_tolerance": 1e-12}),
    ("highs", {"presolve": False}),
    ("highs-ipm", {"presolve": False, "ipm_optimality_tolerance": 1e-12}),
    ("highs-ds", {"presolve": False}),
)

REQUEST_TIME_LIMIT = 60.0


def infeasible_response(req, cert):
    return {
        "epoch": req["epoch"],
        "status": "infeasible",
        "certificate": {
            "inequality": [_san(v) for v in cert["y"].tolist()],
            "equality": [_san(v) for v in cert["q"].tolist()],
        },
    }


def solve_request(req):
    prob = build_problem(req)
    prob["epoch"] = req["epoch"]
    deadline = time.monotonic() + REQUEST_TIME_LIMIT

    best_opt = None
    best_inf = None

    def consider(cand):
        nonlocal best_opt
        if cand is None:
            return False
        if cand["tier"] >= 2:
            return True
        if best_opt is None or cand["tier"] > best_opt["tier"]:
            best_opt = cand
        return False

    def try_optimal(res):
        """Grade an optimal solver result with the available duals."""
        primal = make_primal(prob, res)
        if primal is None:
            return None
        dual = dual_from_marginals(prob, res)
        if dual is not None:
            cand = optimal_response(prob, primal, dual)
            if cand["tier"] >= 1:
                return cand
            # keep the best so far even if only marginal
            consider(cand)
        dual = dual_by_lp(prob)
        if dual is not None:
            cand = optimal_response(prob, primal, dual)
        else:
            cand = None
        return cand

    infeasible = False
    stop = len(OPTIMAL_STRATEGIES)
    for idx, (method, opts) in enumerate(OPTIMAL_STRATEGIES):
        if time.monotonic() > deadline:
            break
        res = _safe_linprog(prob["c"], prob["A_ub"], prob["b_ub"],
                            prob["A_eq"], prob["b_eq"], (0.0, None),
                            method, opts)
        if res is None:
            continue
        if res.status == 0:
            cand = try_optimal(res)
            if cand is not None and consider(cand):
                return cand["response"]
        elif res.status == 2:
            infeasible = True
            stop = idx + 1
            break
        # status 1/3/4: try the next strategy

    if infeasible:
        for gen in (witness_min_rho, witness_phase_one):
            if time.monotonic() > deadline:
                break
            try:
                cert = gen(prob)
            except Exception:
                cert = None
            if cert is None:
                continue
            if cert["tier"] >= 2:
                return infeasible_response(req, cert)
            if best_inf is None or cert["tier"] > best_inf["tier"]:
                best_inf = cert
        if best_inf is not None and best_inf["tier"] >= 1:
            return infeasible_response(req, best_inf)
        # Witness generation failed: the infeasibility verdict may be wrong,
        # so probe the remaining strategies for a primal solution.
        for method, opts in OPTIMAL_STRATEGIES[stop:]:
            if time.monotonic() > deadline:
                break
            res = _safe_linprog(prob["c"], prob["A_ub"], prob["b_ub"],
                                prob["A_eq"], prob["b_eq"], (0.0, None),
                                method, opts)
            if res is not None and res.status == 0:
                cand = try_optimal(res)
                if cand is not None and consider(cand):
                    return cand["response"]

    if best_opt is not None and best_opt["tier"] >= 1:
        return best_opt["response"]
    if best_inf is not None:
        return infeasible_response(req, best_inf)
    if best_opt is not None:
        return best_opt["response"]
    # Nothing worked at all; report infeasible with an empty witness rather
    # than crashing the process.
    return {
        "epoch": req["epoch"],
        "status": "infeasible",
        "certificate": {
            "inequality": [0.0] * prob["R"],
            "equality": [0.0] * prob["K"],
        },
    }


'''
src = src[:start] + new + src[end:]
src = src.replace("import json\nimport sys\n", "import json\nimport sys\nimport time\n")
open('/app/submission/planner.py','w').write(src)
